// Hot batch 241: sixty-instruction functions no route reaches, written by hand from `tools.disasm` and verified by synthetic
// cases (handle-guarded calls through temporaries, clamped gauges and string releases).
// No names: none has evidence.
#include "decomp_registry.hpp"
